-- Märkmik database. Applied on every start (CREATE ... IF NOT EXISTS), so it must stay idempotent.
-- Frozen: work packages do not edit this file; changes go through the lead (docs/CONTRACTS.md).
-- Times are UTC ISO-8601 text ('2026-09-24T08:15:00Z') unless a column says otherwise.

CREATE TABLE IF NOT EXISTS owner (
  id            INTEGER PRIMARY KEY CHECK (id = 1),
  password_hash TEXT    NOT NULL
);

CREATE TABLE IF NOT EXISTS settings (
  key   TEXT PRIMARY KEY,
  value TEXT NOT NULL
);

-- Encrypted with Fernet (app/vault.py). Never sent to the browser in clear.
CREATE TABLE IF NOT EXISTS secrets (
  name       TEXT PRIMARY KEY,
  ciphertext BLOB NOT NULL,
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now'))
);

-- First-run wizard: step -> 'done' | 'skipped'.
CREATE TABLE IF NOT EXISTS onboarding (
  step   TEXT PRIMARY KEY,
  status TEXT NOT NULL CHECK (status IN ('done', 'skipped'))
);

-- body is Markdown without frontmatter; links inside it use /m/<slug>.
-- rev grows on every write of body; exported_rev is the rev last written to git.
CREATE TABLE IF NOT EXISTS notes (
  id                INTEGER PRIMARY KEY AUTOINCREMENT,
  slug              TEXT    NOT NULL UNIQUE,
  title             TEXT    NOT NULL DEFAULT '',
  body              TEXT    NOT NULL DEFAULT '',
  folder            TEXT    NOT NULL DEFAULT '',          -- 'kool/matemaatika', '' = root
  tags_json         TEXT    NOT NULL DEFAULT '[]',
  aliases_json      TEXT    NOT NULL DEFAULT '[]',
  frontmatter_extra TEXT    NOT NULL DEFAULT '{}',        -- unknown frontmatter keys kept for git
  pinned            INTEGER NOT NULL DEFAULT 0,
  is_daily          INTEGER NOT NULL DEFAULT 0,
  daily_date        TEXT UNIQUE,                          -- 'YYYY-MM-DD' for daily notes
  created_at        TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
  updated_at        TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
  deleted_at        TEXT,
  rev               INTEGER NOT NULL DEFAULT 1,
  exported_rev      INTEGER NOT NULL DEFAULT 0,
  file_path         TEXT                                  -- path in the brain repo, set by gitsync
);
CREATE INDEX IF NOT EXISTS notes_folder ON notes (folder) WHERE deleted_at IS NULL;

-- Full-text search over live notes. External content: the triggers below keep it in sync.
-- remove_diacritics 2 folds õäöü, so "too" finds "töö".
CREATE VIRTUAL TABLE IF NOT EXISTS notes_fts USING fts5 (
  title, body,
  content = 'notes', content_rowid = 'id',
  tokenize = 'unicode61 remove_diacritics 2'
);
CREATE TRIGGER IF NOT EXISTS notes_fts_ai AFTER INSERT ON notes BEGIN
  INSERT INTO notes_fts (rowid, title, body) VALUES (new.id, new.title, new.body);
END;
CREATE TRIGGER IF NOT EXISTS notes_fts_ad AFTER DELETE ON notes BEGIN
  INSERT INTO notes_fts (notes_fts, rowid, title, body) VALUES ('delete', old.id, old.title, old.body);
END;
CREATE TRIGGER IF NOT EXISTS notes_fts_au AFTER UPDATE OF title, body ON notes BEGIN
  INSERT INTO notes_fts (notes_fts, rowid, title, body) VALUES ('delete', old.id, old.title, old.body);
  INSERT INTO notes_fts (rowid, title, body) VALUES (new.id, new.title, new.body);
END;

-- Rebuilt from a note's body on every save (notes.on_saved). dst_id is NULL for a missing note.
CREATE TABLE IF NOT EXISTS links (
  src_id   INTEGER NOT NULL REFERENCES notes (id) ON DELETE CASCADE,
  dst_slug TEXT    NOT NULL,
  dst_id   INTEGER REFERENCES notes (id) ON DELETE SET NULL,
  anchor   TEXT    NOT NULL DEFAULT ''
);
CREATE INDEX IF NOT EXISTS links_src ON links (src_id);
CREATE INDEX IF NOT EXISTS links_dst ON links (dst_slug);

-- Task lines ("- [ ] text @date") parsed from note bodies on save. line_key identifies the line
-- across saves (text hash + occurrence), so a toggle finds it again.
CREATE TABLE IF NOT EXISTS tasks (
  id       INTEGER PRIMARY KEY AUTOINCREMENT,
  note_id  INTEGER NOT NULL REFERENCES notes (id) ON DELETE CASCADE,
  line_key TEXT    NOT NULL,
  text     TEXT    NOT NULL,
  done     INTEGER NOT NULL DEFAULT 0,
  due_date TEXT,                                          -- 'YYYY-MM-DD' local
  due_time TEXT,                                          -- 'HH:MM' local
  UNIQUE (note_id, line_key)
);
CREATE INDEX IF NOT EXISTS tasks_due ON tasks (due_date);

-- Live co-editing (app/collab.py). A session is valid while closed = 0 and notes.rev = note_rev.
CREATE TABLE IF NOT EXISTS collab_sessions (
  id             INTEGER PRIMARY KEY AUTOINCREMENT,
  note_id        INTEGER NOT NULL REFERENCES notes (id) ON DELETE CASCADE,
  base           TEXT    NOT NULL,
  note_rev       INTEGER NOT NULL,
  saved_seq      INTEGER NOT NULL DEFAULT 0,
  closed         INTEGER NOT NULL DEFAULT 0,
  last_active_at TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
  created_at     TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now'))
);
CREATE INDEX IF NOT EXISTS collab_sessions_note ON collab_sessions (note_id, id);

CREATE TABLE IF NOT EXISTS collab_ops (
  session_id INTEGER NOT NULL REFERENCES collab_sessions (id) ON DELETE CASCADE,
  seq        INTEGER NOT NULL,
  op         TEXT    NOT NULL,
  client     TEXT    NOT NULL,
  op_id      TEXT    NOT NULL,
  author     TEXT    NOT NULL,
  created_at TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
  PRIMARY KEY (session_id, seq)
);
-- Resent operations are recognised by (client, op_id).
CREATE INDEX IF NOT EXISTS collab_ops_op_id ON collab_ops (session_id, client, op_id);

CREATE TABLE IF NOT EXISTS images (
  name          TEXT PRIMARY KEY,                         -- sha1 + extension
  original_name TEXT NOT NULL DEFAULT '',
  author        TEXT NOT NULL DEFAULT '',
  created_at    TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now'))
);

-- Pictures a share-link guest of the note may load (app/images.py): the note's pictures when a
-- link was made, the owner's uploads into the note, and guests' uploads through its links.
CREATE TABLE IF NOT EXISTS note_images (
  note_id INTEGER NOT NULL REFERENCES notes (id) ON DELETE CASCADE,
  name    TEXT    NOT NULL,                               -- images.name
  PRIMARY KEY (note_id, name)
);

-- Calendar. Timed events: start_at/end_at UTC + tzid. All-day: start_date/end_date (end exclusive).
-- A recurring series has rrule (+ exdates_json); an overridden occurrence is its own row with
-- series_id = the series and recurrence_id = the original occurrence start (UTC or date).
CREATE TABLE IF NOT EXISTS events (
  id            INTEGER PRIMARY KEY AUTOINCREMENT,
  uid           TEXT    NOT NULL UNIQUE,
  title         TEXT    NOT NULL,
  start_at      TEXT,
  end_at        TEXT,
  start_date    TEXT,
  end_date      TEXT,
  all_day       INTEGER NOT NULL DEFAULT 0,
  tzid          TEXT    NOT NULL DEFAULT 'Europe/Tallinn',
  kind          TEXT    NOT NULL DEFAULT 'sündmus'
                CHECK (kind IN ('tund', 'kontrolltöö', 'kodutöö', 'sündmus', 'tähtaeg', 'isiklik')),
  status        TEXT    NOT NULL DEFAULT 'kinnitatud'
                CHECK (status IN ('kinnitatud', 'pakutud', 'eemaldatud')),
  source        TEXT    NOT NULL DEFAULT 'käsitsi'
                CHECK (source IN ('käsitsi', 'ekool', 'gmail', 'ics', 'ai')),
  source_ref    TEXT,                                     -- e.g. 'gmail:<account>:<message id>'
  source_quote  TEXT,
  confidence    TEXT CHECK (confidence IN ('low', 'med', 'high')),
  location      TEXT    NOT NULL DEFAULT '',
  description   TEXT    NOT NULL DEFAULT '',
  note_id       INTEGER REFERENCES notes (id) ON DELETE SET NULL,
  rrule         TEXT,
  exdates_json  TEXT    NOT NULL DEFAULT '[]',
  series_id     INTEGER REFERENCES events (id) ON DELETE CASCADE,
  recurrence_id TEXT,
  user_edited   INTEGER NOT NULL DEFAULT 0,
  created_at    TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
  updated_at    TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
  CHECK ((all_day = 1 AND start_date IS NOT NULL) OR (all_day = 0 AND start_at IS NOT NULL))
);
CREATE INDEX IF NOT EXISTS events_start_at ON events (start_at);
CREATE INDEX IF NOT EXISTS events_start_date ON events (start_date);
CREATE INDEX IF NOT EXISTS events_status ON events (status);

-- Done flag per occurrence ('' for a non-recurring event).
CREATE TABLE IF NOT EXISTS event_done (
  event_id   INTEGER NOT NULL REFERENCES events (id) ON DELETE CASCADE,
  occurrence TEXT    NOT NULL DEFAULT '',
  PRIMARY KEY (event_id, occurrence)
);

-- A reminder the user asked for (docs/KODU-PLAN.md): one push at remind_at (UTC). Not an event;
-- events keep their rule-based reminders. event_id: the event it is about (a removed event's
-- reminder is not sent).
CREATE TABLE IF NOT EXISTS reminders (
  id         INTEGER PRIMARY KEY AUTOINCREMENT,
  text       TEXT    NOT NULL,
  remind_at  TEXT    NOT NULL,
  event_id   INTEGER REFERENCES events (id) ON DELETE SET NULL,
  note_id    INTEGER REFERENCES notes (id) ON DELETE SET NULL,
  source     TEXT    NOT NULL DEFAULT 'käsitsi' CHECK (source IN ('käsitsi', 'ai')),
  done_at    TEXT,
  sent_at    TEXT,
  created_at TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now'))
);
CREATE INDEX IF NOT EXISTS reminders_remind_at ON reminders (remind_at);

-- item_kind: 'event' | 'task' | 'reminder' (rule 'at', occurrence = its remind_at).
CREATE TABLE IF NOT EXISTS reminders_sent (
  item_kind  TEXT    NOT NULL,
  item_id    INTEGER NOT NULL,
  occurrence TEXT    NOT NULL DEFAULT '',
  rule       TEXT    NOT NULL,
  sent_at    TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
  PRIMARY KEY (item_kind, item_id, occurrence, rule)
);

-- kind: 'ekool' | 'gmail' | 'ics'. Credentials live in secrets, not config_json.
CREATE TABLE IF NOT EXISTS sources (
  id          INTEGER PRIMARY KEY AUTOINCREMENT,
  kind        TEXT NOT NULL CHECK (kind IN ('ekool', 'gmail', 'ics')),
  name        TEXT NOT NULL,
  config_json TEXT NOT NULL DEFAULT '{}',
  cursor      TEXT,
  enabled     INTEGER NOT NULL DEFAULT 1,
  last_run_at TEXT,
  last_ok_at  TEXT,
  last_error  TEXT,
  UNIQUE (kind, name)
);

-- status: 'new' | 'done' | 'skipped' | 'error'.
CREATE TABLE IF NOT EXISTS source_items (
  id          INTEGER PRIMARY KEY AUTOINCREMENT,
  source_id   INTEGER NOT NULL REFERENCES sources (id) ON DELETE CASCADE,
  external_id TEXT    NOT NULL,
  fetched_at  TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
  raw_json    TEXT    NOT NULL,
  status      TEXT    NOT NULL DEFAULT 'new',
  error       TEXT,
  UNIQUE (source_id, external_id)
);
CREATE INDEX IF NOT EXISTS source_items_status ON source_items (status);

-- An AI or source item the user removed or rejected never comes back.
CREATE TABLE IF NOT EXISTS rejected_uids (
  uid TEXT PRIMARY KEY
);

-- The competition finder's participation facts of a proposed competition (app/voistlused.py,
-- app/eligibility.py): grades, level, team, qualification, registration, fee, place, qualifier.
CREATE TABLE IF NOT EXISTS voistlus_info (
  uid       TEXT PRIMARY KEY,                             -- events.uid of the competition
  info_json TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS ai_usage (
  day   TEXT PRIMARY KEY,                                 -- 'YYYY-MM-DD' local
  calls INTEGER NOT NULL DEFAULT 0
);

-- token_hash = sha256 hex of the URL token; mode 'view' | 'edit'.
CREATE TABLE IF NOT EXISTS shares (
  id           INTEGER PRIMARY KEY AUTOINCREMENT,
  token_hash   TEXT    NOT NULL UNIQUE,
  note_id      INTEGER NOT NULL REFERENCES notes (id) ON DELETE CASCADE,
  mode         TEXT    NOT NULL CHECK (mode IN ('view', 'edit')),
  created_at   TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
  expires_at   TEXT,
  revoked_at   TEXT,
  last_used_at TEXT
);

CREATE TABLE IF NOT EXISTS ai_threads (
  id         INTEGER PRIMARY KEY AUTOINCREMENT,
  note_id    INTEGER REFERENCES notes (id) ON DELETE CASCADE,
  session_id TEXT,                                        -- Claude session id for resume
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now'))
);

CREATE TABLE IF NOT EXISTS ai_messages (
  id           INTEGER PRIMARY KEY AUTOINCREMENT,
  thread_id    INTEGER NOT NULL REFERENCES ai_threads (id) ON DELETE CASCADE,
  role         TEXT    NOT NULL CHECK (role IN ('user', 'assistant', 'tool')),
  content_json TEXT    NOT NULL,
  created_at   TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now'))
);

-- Aktsiad (docs/AKTSIAD-PLAN.md): the watchlist, prices, holdings, news and the AI research that
-- came over from stock-oracle. Money, quantities and rates are Decimal as TEXT (str(Decimal)):
-- SQL never sorts or sums them, Python does. Dates without a time are 'YYYY-MM-DD'.

-- provider_symbols_json: {"yahoo": "VWCE.DE", "finnhub": null, "sec_cik": "..."}; null = not covered.
CREATE TABLE IF NOT EXISTS instruments (
  id                    INTEGER PRIMARY KEY AUTOINCREMENT,
  symbol                TEXT NOT NULL,
  exchange              TEXT NOT NULL,
  currency              TEXT NOT NULL,
  name                  TEXT NOT NULL,
  kind                  TEXT NOT NULL CHECK (kind IN ('stock', 'etf', 'index')),
  isin                  TEXT UNIQUE,
  sector                TEXT,
  provider_symbols_json TEXT NOT NULL DEFAULT '{}',
  created_at            TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
  UNIQUE (symbol, exchange)
);

CREATE TABLE IF NOT EXISTS watchlist (
  instrument_id INTEGER PRIMARY KEY REFERENCES instruments (id) ON DELETE CASCADE,
  added_at      TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
  note          TEXT,
  tags_json     TEXT NOT NULL DEFAULT '[]'
);

-- OHLC split-adjusted as the source gives it; adj_close also for dividends.
CREATE TABLE IF NOT EXISTS price_bars (
  id            INTEGER PRIMARY KEY AUTOINCREMENT,
  instrument_id INTEGER NOT NULL REFERENCES instruments (id) ON DELETE CASCADE,
  date          TEXT    NOT NULL,
  open          TEXT,
  high          TEXT,
  low           TEXT,
  close         TEXT    NOT NULL,
  adj_close     TEXT,
  volume        INTEGER,
  source        TEXT    NOT NULL,
  fetched_at    TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
  UNIQUE (instrument_id, date, source)
);

-- The latest daytime quote per instrument (a cache, overwritten).
CREATE TABLE IF NOT EXISTS quotes (
  instrument_id  INTEGER PRIMARY KEY REFERENCES instruments (id) ON DELETE CASCADE,
  price          TEXT NOT NULL,
  previous_close TEXT,
  as_of          TEXT NOT NULL,
  source         TEXT NOT NULL,
  fetched_at     TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now'))
);

-- date = ex-date. Split: new shares per old share (4-for-1 = '4'). Dividend: amount per share.
CREATE TABLE IF NOT EXISTS corporate_actions (
  id            INTEGER PRIMARY KEY AUTOINCREMENT,
  instrument_id INTEGER NOT NULL REFERENCES instruments (id) ON DELETE CASCADE,
  date          TEXT    NOT NULL,
  kind          TEXT    NOT NULL CHECK (kind IN ('split', 'dividend')),
  ratio         TEXT,
  amount        TEXT,
  currency      TEXT,
  source        TEXT    NOT NULL,
  UNIQUE (instrument_id, date, kind, source),
  CHECK ((kind = 'split' AND ratio IS NOT NULL) OR (kind = 'dividend' AND amount IS NOT NULL AND currency IS NOT NULL))
);

-- ECB reference rate: 1 base = rate quote.
CREATE TABLE IF NOT EXISTS fx_rates (
  date  TEXT NOT NULL,
  base  TEXT NOT NULL,
  quote TEXT NOT NULL,
  rate  TEXT NOT NULL,
  PRIMARY KEY (date, base, quote)
);

-- investment_account = the Estonian investeerimiskonto (app/stocks/portfolio/investment_account.py).
CREATE TABLE IF NOT EXISTS broker_accounts (
  id            INTEGER PRIMARY KEY AUTOINCREMENT,
  name          TEXT NOT NULL UNIQUE,
  broker        TEXT NOT NULL,
  base_currency TEXT NOT NULL DEFAULT 'EUR',
  kind          TEXT NOT NULL CHECK (kind IN ('brokerage', 'investment_account')),
  created_at    TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now'))
);

-- A transaction exactly as entered or imported, never adjusted: splits apply at read time.
-- amount: cash for deposit/withdrawal/fee/interest, gross for a dividend. ts is UTC ('...Z').
-- Positivity of qty/price/amount/ratio is checked in code (the values are TEXT here).
CREATE TABLE IF NOT EXISTS portfolio_tx (
  id            INTEGER PRIMARY KEY AUTOINCREMENT,
  account_id    INTEGER NOT NULL REFERENCES broker_accounts (id) ON DELETE RESTRICT,
  instrument_id INTEGER REFERENCES instruments (id) ON DELETE RESTRICT,
  kind          TEXT    NOT NULL CHECK (kind IN ('buy', 'sell', 'dividend', 'fee', 'deposit', 'withdrawal', 'split', 'interest')),
  ts            TEXT    NOT NULL,
  qty           TEXT,
  price         TEXT,
  amount        TEXT,
  ratio         TEXT,
  currency      TEXT    NOT NULL,
  fee           TEXT    NOT NULL DEFAULT '0',
  tax_withheld  TEXT    NOT NULL DEFAULT '0',
  note          TEXT,
  external_ref  TEXT,
  created_at    TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
  UNIQUE (account_id, external_ref),
  CHECK ((kind IN ('buy', 'sell') AND instrument_id IS NOT NULL AND qty IS NOT NULL AND price IS NOT NULL)
      OR (kind = 'dividend' AND instrument_id IS NOT NULL AND amount IS NOT NULL)
      OR (kind = 'split' AND instrument_id IS NOT NULL AND ratio IS NOT NULL)
      OR (kind IN ('deposit', 'withdrawal', 'fee', 'interest') AND amount IS NOT NULL))
);
CREATE INDEX IF NOT EXISTS portfolio_tx_account ON portfolio_tx (account_id, ts);
CREATE INDEX IF NOT EXISTS portfolio_tx_instrument ON portfolio_tx (instrument_id, ts);

-- A collected news item, filing or post, full text. Deduplicated by (source, external_id) and by
-- url_hash (sha256 of the normalised URL); content_hash (normalised title + body) is not unique.
CREATE TABLE IF NOT EXISTS market_docs (
  id           INTEGER PRIMARY KEY AUTOINCREMENT,
  source       TEXT NOT NULL,
  external_id  TEXT,
  url          TEXT,
  url_hash     TEXT UNIQUE,
  content_hash TEXT NOT NULL,
  title        TEXT,
  body         TEXT,
  author       TEXT,
  language     TEXT,
  published_at TEXT,
  fetched_at   TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
  meta_json    TEXT NOT NULL DEFAULT '{}',
  UNIQUE (source, external_id)
);
CREATE INDEX IF NOT EXISTS market_docs_content ON market_docs (content_hash);
CREATE INDEX IF NOT EXISTS market_docs_published ON market_docs (published_at);

CREATE TABLE IF NOT EXISTS market_doc_instruments (
  document_id   INTEGER NOT NULL REFERENCES market_docs (id) ON DELETE CASCADE,
  instrument_id INTEGER NOT NULL REFERENCES instruments (id) ON DELETE CASCADE,
  PRIMARY KEY (document_id, instrument_id)
);
CREATE INDEX IF NOT EXISTS market_doc_instruments_instrument ON market_doc_instruments (instrument_id);

-- The model's per-document reading for one instrument. sentiment -1..1, novelty and relevance 0..1.
CREATE TABLE IF NOT EXISTS doc_signals (
  id             INTEGER PRIMARY KEY AUTOINCREMENT,
  document_id    INTEGER NOT NULL REFERENCES market_docs (id) ON DELETE CASCADE,
  instrument_id  INTEGER NOT NULL REFERENCES instruments (id) ON DELETE CASCADE,
  ai_run_id      INTEGER REFERENCES stock_ai_runs (id) ON DELETE SET NULL,
  sentiment      TEXT    NOT NULL,
  event_type     TEXT    NOT NULL,
  novelty        TEXT    NOT NULL,
  relevance      TEXT    NOT NULL,
  summary        TEXT    NOT NULL,
  key_facts_json TEXT    NOT NULL DEFAULT '[]',
  prompt_version TEXT    NOT NULL,
  created_at     TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
  UNIQUE (document_id, instrument_id, prompt_version)
);
CREATE INDEX IF NOT EXISTS doc_signals_instrument ON doc_signals (instrument_id, created_at);

-- A Form 4 transaction. code: the form's transaction code (P, S, A, M, ...).
CREATE TABLE IF NOT EXISTS insider_trades (
  id            INTEGER PRIMARY KEY AUTOINCREMENT,
  instrument_id INTEGER NOT NULL REFERENCES instruments (id) ON DELETE CASCADE,
  document_id   INTEGER NOT NULL REFERENCES market_docs (id) ON DELETE CASCADE,
  insider_name  TEXT    NOT NULL,
  insider_role  TEXT,
  trade_date    TEXT    NOT NULL,
  kind          TEXT    NOT NULL CHECK (kind IN ('buy', 'sell', 'other')),
  code          TEXT    NOT NULL,
  qty           TEXT    NOT NULL,
  price         TEXT,
  shares_after  TEXT
);
CREATE INDEX IF NOT EXISTS insider_trades_instrument ON insider_trades (instrument_id, trade_date);

-- time_of_day: 'bmo' (before open), 'amc' (after close) or NULL.
CREATE TABLE IF NOT EXISTS earnings (
  id               INTEGER PRIMARY KEY AUTOINCREMENT,
  instrument_id    INTEGER NOT NULL REFERENCES instruments (id) ON DELETE CASCADE,
  date             TEXT    NOT NULL,
  time_of_day      TEXT,
  fiscal_period    TEXT,
  eps_estimate     TEXT,
  eps_actual       TEXT,
  revenue_estimate TEXT,
  revenue_actual   TEXT,
  source           TEXT    NOT NULL,
  updated_at       TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
  UNIQUE (instrument_id, date, source)
);

-- Documents per instrument, day and source, for the attention alert (a 30-day z-score).
CREATE TABLE IF NOT EXISTS doc_counts (
  instrument_id INTEGER NOT NULL REFERENCES instruments (id) ON DELETE CASCADE,
  date          TEXT    NOT NULL,
  source        TEXT    NOT NULL,
  count         INTEGER NOT NULL,
  PRIMARY KEY (instrument_id, date, source)
);

-- One nightly run (app/stocks/night.py). run_date: the Tallinn date of its night.
-- steps_json: {"step": {"status", "started_at", "finished_at", "detail"}}.
CREATE TABLE IF NOT EXISTS stock_runs (
  id          INTEGER PRIMARY KEY AUTOINCREMENT,
  run_date    TEXT NOT NULL,
  started_at  TEXT NOT NULL,
  finished_at TEXT,
  status      TEXT NOT NULL CHECK (status IN ('running', 'succeeded', 'partial', 'failed', 'skipped')),
  steps_json  TEXT NOT NULL DEFAULT '{}'
);
CREATE INDEX IF NOT EXISTS stock_runs_date ON stock_runs (run_date);

-- One model call of the stocks package, successful or not (app/stocks/aicall.py).
CREATE TABLE IF NOT EXISTS stock_ai_runs (
  id             INTEGER PRIMARY KEY AUTOINCREMENT,
  run_id         INTEGER REFERENCES stock_runs (id) ON DELETE SET NULL,
  purpose        TEXT    NOT NULL CHECK (purpose IN ('extract', 'discover', 'research', 'deep_dive', 'explore', 'verdict')),
  instrument_id  INTEGER REFERENCES instruments (id) ON DELETE SET NULL,
  model          TEXT    NOT NULL,
  prompt_version TEXT    NOT NULL,
  started_at     TEXT    NOT NULL,
  duration_ms    INTEGER,
  status         TEXT    NOT NULL CHECK (status IN ('running', 'success', 'unavailable', 'failed')),
  error          TEXT
);
CREATE INDEX IF NOT EXISTS stock_ai_runs_started ON stock_ai_runs (started_at);

-- kind 'deep' is one per stock and night; 'on_demand' (Uuri kohe) may be several a day.
-- bull/bear: [{text, citation}] with citation an index into citations_json [{url, title, quote, published_at}].
CREATE TABLE IF NOT EXISTS analyses (
  id                  INTEGER PRIMARY KEY AUTOINCREMENT,
  instrument_id       INTEGER NOT NULL REFERENCES instruments (id) ON DELETE CASCADE,
  ai_run_id           INTEGER REFERENCES stock_ai_runs (id) ON DELETE SET NULL,
  kind                TEXT    NOT NULL CHECK (kind IN ('deep', 'on_demand')),
  as_of               TEXT    NOT NULL,
  summary             TEXT    NOT NULL,
  what_changed        TEXT,
  bull_json           TEXT    NOT NULL DEFAULT '[]',
  bear_json           TEXT    NOT NULL DEFAULT '[]',
  catalysts_json      TEXT    NOT NULL DEFAULT '[]',
  risks_json          TEXT    NOT NULL DEFAULT '[]',
  change_my_mind_json TEXT    NOT NULL DEFAULT '[]',
  citations_json      TEXT    NOT NULL DEFAULT '[]',
  prompt_version      TEXT    NOT NULL,
  model               TEXT    NOT NULL,
  created_at          TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now'))
);
CREATE INDEX IF NOT EXISTS analyses_instrument ON analyses (instrument_id, as_of);
CREATE UNIQUE INDEX IF NOT EXISTS analyses_deep_once ON analyses (instrument_id, as_of) WHERE kind = 'deep';

-- The nightly would buy / hold / sell call, one per stock and night. inputs_json: what the model
-- was shown, for auditing a call later.
CREATE TABLE IF NOT EXISTS verdicts (
  id                     INTEGER PRIMARY KEY AUTOINCREMENT,
  instrument_id          INTEGER NOT NULL REFERENCES instruments (id) ON DELETE CASCADE,
  ai_run_id              INTEGER REFERENCES stock_ai_runs (id) ON DELETE SET NULL,
  run_id                 INTEGER REFERENCES stock_runs (id) ON DELETE SET NULL,
  as_of                  TEXT    NOT NULL,
  verdict                TEXT    NOT NULL CHECK (verdict IN ('buy', 'hold', 'sell')),
  conviction             TEXT    NOT NULL CHECK (conviction IN ('low', 'medium', 'high')),
  summary                TEXT    NOT NULL,
  reasons_for_json       TEXT    NOT NULL DEFAULT '[]',
  reasons_against_json   TEXT    NOT NULL DEFAULT '[]',
  what_would_change_json TEXT    NOT NULL DEFAULT '[]',
  inputs_json            TEXT    NOT NULL DEFAULT '{}',
  prompt_version         TEXT    NOT NULL,
  model                  TEXT    NOT NULL,
  created_at             TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
  UNIQUE (instrument_id, as_of)
);

-- One Avasta (Explore) run: ideas outside the watchlist; dropped_json: links and ideas the
-- cross-check removed, each with the reason.
CREATE TABLE IF NOT EXISTS explorations (
  id              INTEGER PRIMARY KEY AUTOINCREMENT,
  ai_run_id       INTEGER REFERENCES stock_ai_runs (id) ON DELETE SET NULL,
  focus           TEXT,
  requested_ideas INTEGER NOT NULL,
  market_context  TEXT    NOT NULL,
  ideas_json      TEXT    NOT NULL DEFAULT '[]',
  dropped_json    TEXT    NOT NULL DEFAULT '[]',
  prompt_version  TEXT    NOT NULL,
  model           TEXT    NOT NULL,
  created_at      TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now'))
);

-- One ingest attempt of one news source, for the Allikad tab. cursor_json: where the next run
-- continues ({"until": "...Z"}).
CREATE TABLE IF NOT EXISTS stock_source_runs (
  id            INTEGER PRIMARY KEY AUTOINCREMENT,
  run_id        INTEGER REFERENCES stock_runs (id) ON DELETE SET NULL,
  source        TEXT    NOT NULL,
  started_at    TEXT    NOT NULL,
  finished_at   TEXT,
  status        TEXT    NOT NULL CHECK (status IN ('running', 'succeeded', 'partial', 'failed', 'skipped')),
  items_fetched INTEGER NOT NULL DEFAULT 0,
  items_new     INTEGER NOT NULL DEFAULT 0,
  cursor_json   TEXT,
  error         TEXT
);
CREATE INDEX IF NOT EXISTS stock_source_runs_source ON stock_source_runs (source, started_at);

-- A stocks alert or digest, sent once: dedupe_key e.g. '8k:<accession>' or 'digest:2026-09-30'.
CREATE TABLE IF NOT EXISTS stock_notices (
  id         INTEGER PRIMARY KEY AUTOINCREMENT,
  dedupe_key TEXT NOT NULL UNIQUE,
  kind       TEXT NOT NULL,
  title      TEXT NOT NULL,
  body       TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
  sent_at    TEXT,
  error      TEXT
);

-- Meedia (docs/MEEDIA-PLAN.md): an index over the flat media folder. Each file's companion file
-- (<name>.json beside it) is the truth; `python -m app.meedia.reindex` rebuilds these tables from
-- the folder. data_json is the companion as last indexed, so a lost companion can be written back.
CREATE TABLE IF NOT EXISTS media (
  id              INTEGER PRIMARY KEY AUTOINCREMENT,
  name            TEXT    NOT NULL UNIQUE,              -- file name in the media root
  sha256          TEXT    NOT NULL,
  kind            TEXT    NOT NULL CHECK (kind IN ('image', 'video')),
  mime            TEXT    NOT NULL,
  bytes           INTEGER NOT NULL,
  width           INTEGER,
  height          INTEGER,
  duration        REAL,                                 -- seconds, videos only
  taken_at        TEXT,                                 -- from EXIF / the video's metadata
  added_at        TEXT    NOT NULL,
  title           TEXT    NOT NULL DEFAULT '',
  description     TEXT    NOT NULL DEFAULT '',
  ocr             TEXT    NOT NULL DEFAULT '',
  tags_text       TEXT    NOT NULL DEFAULT '',          -- tags and auto_tags, space-separated, for media_fts
  data_json       TEXT    NOT NULL,
  companion_mtime INTEGER NOT NULL                      -- st_mtime_ns; another value on disk = a hand edit
);
CREATE INDEX IF NOT EXISTS media_sha256 ON media (sha256);
CREATE INDEX IF NOT EXISTS media_when ON media (coalesce(taken_at, added_at));

-- One row per tag of a file; auto = 1 when only the model gave it.
CREATE TABLE IF NOT EXISTS media_tags (
  media_id INTEGER NOT NULL REFERENCES media (id) ON DELETE CASCADE,
  tag      TEXT    NOT NULL,
  auto     INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (media_id, tag)
);
CREATE INDEX IF NOT EXISTS media_tags_tag ON media_tags (tag);

CREATE VIRTUAL TABLE IF NOT EXISTS media_fts USING fts5 (
  name, title, description, tags_text, ocr,
  content = 'media', content_rowid = 'id',
  tokenize = 'unicode61 remove_diacritics 2'
);
CREATE TRIGGER IF NOT EXISTS media_fts_ai AFTER INSERT ON media BEGIN
  INSERT INTO media_fts (rowid, name, title, description, tags_text, ocr)
  VALUES (new.id, new.name, new.title, new.description, new.tags_text, new.ocr);
END;
CREATE TRIGGER IF NOT EXISTS media_fts_ad AFTER DELETE ON media BEGIN
  INSERT INTO media_fts (media_fts, rowid, name, title, description, tags_text, ocr)
  VALUES ('delete', old.id, old.name, old.title, old.description, old.tags_text, old.ocr);
END;
CREATE TRIGGER IF NOT EXISTS media_fts_au AFTER UPDATE OF name, title, description, tags_text, ocr ON media BEGIN
  INSERT INTO media_fts (media_fts, rowid, name, title, description, tags_text, ocr)
  VALUES ('delete', old.id, old.name, old.title, old.description, old.tags_text, old.ocr);
  INSERT INTO media_fts (rowid, name, title, description, tags_text, ocr)
  VALUES (new.id, new.name, new.title, new.description, new.tags_text, new.ocr);
END;

-- A file found in the folder without a companion file: taken in once its size and mtime hold
-- between two scans, so a copy still in progress is left alone.
CREATE TABLE IF NOT EXISTS media_pending (
  name     TEXT    PRIMARY KEY,
  bytes    INTEGER NOT NULL,
  mtime_ns INTEGER NOT NULL
);
